import React, { useState } from 'react';
import { ListBox } from 'primereact/listbox';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="listBox-accessibility">Accessible ListBox</label>
            <ListBox 
                id="listBox-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible ListBox input"
                placeholder="Enter listBox"
            />
        </div>
    );
}